<script lang="ts">
 import {onDestroy,tick} from 'svelte';
 import {getWorkbenchI18nContext,createWorkbenchI18nContext} from '../i18n/workbenchI18n';
 import {workbenchUiFrenchBundle} from '../i18n/workbenchUiFrenchTranslations';
 import {workbenchUiEnglishBundle} from '../i18n/workbenchUiTranslations';
 import {workbenchUiChineseBundle} from '../i18n/workbenchUiChineseTranslations';
 import {serializeExperienceTransfer,type ExperienceTransferArtifact,type ExperienceTransferProfile} from '@konitif/workbench';
 import StructuredValueNode from './StructuredValueNode.svelte';
 import {renderExperienceCardImage} from './experienceCardImage';
 export let open=false;export let capture:(profile:ExperienceTransferProfile)=>Promise<ExperienceTransferArtifact>;export let onClose:()=>void=()=>{};
 export let locale='en';
 const inherited=getWorkbenchI18nContext(),fallback=createWorkbenchI18nContext({bundles:[workbenchUiFrenchBundle,workbenchUiEnglishBundle,workbenchUiChineseBundle]});
 const t=(inherited??fallback).t;
 $: if(!inherited)fallback.locale.set(locale);
 let definitionMode:'tree'|'json'='tree';
 let profile:ExperienceTransferProfile='distribution',card:ExperienceTransferArtifact|undefined,url='',error='',busy=false,generation=0,wasOpen=false,panel:HTMLElement;
 $: {if(open&&!wasOpen){profile='distribution';void refresh();} wasOpen=open;}
 async function refresh(){const token=++generation;busy=true;error='';card=undefined;if(url)URL.revokeObjectURL(url);url='';try{const next=await capture(profile),image=await renderExperienceCardImage(next);if(token!==generation)return;card=next;url=URL.createObjectURL(image);await tick();panel?.focus();}catch(cause){if(token===generation)error=cause instanceof Error?cause.message:String(cause);}finally{if(token===generation)busy=false;}}
 function close(){generation++;busy=false;if(url)URL.revokeObjectURL(url);url='';card=undefined;onClose();}
 function download(kind:'png'|'json'){if(!card)return;const a=document.createElement('a');a.href=kind==='png'?url:URL.createObjectURL(new Blob([serializeExperienceTransfer(card)],{type:'application/json'}));a.download=`${card.profile}-${card.contentId.slice(0,12)}.experience.${kind}`;a.click();if(kind==='json')setTimeout(()=>URL.revokeObjectURL(a.href),0);}
 function drag(e:DragEvent){if(!card||!e.dataTransfer)return;e.dataTransfer.setData('application/vnd.konitif.experience-transfer+json',serializeExperienceTransfer(card));e.dataTransfer.setData('text/plain',serializeExperienceTransfer(card));e.dataTransfer.effectAllowed='copy';}
 function key(e:KeyboardEvent){if(!open)return;if(e.key==='Escape'){e.preventDefault();close();}if(e.key==='Tab'&&panel){const all=Array.from(panel.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),a[href],summary'));const first=all[0],last=all[all.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}}
 onDestroy(()=>{generation++;if(url)URL.revokeObjectURL(url);});
</script>
<svelte:window on:keydown={key}/>
{#if open}<div class="share-overlay" role="presentation"><button class="backdrop" aria-label={$t('ui.shell.experienceShare.close',{default:'Close experience sharing'})} on:click={close}></button><div class="share-panel" bind:this={panel} tabindex="-1" role="dialog" aria-modal="true" aria-labelledby="experience-share-title">
 <header><h2 id="experience-share-title">{$t('ui.shell.experienceShare.title',{default:'Share experience'})}</h2><button aria-label={$t('ui.shell.experienceShare.close',{default:'Close experience sharing'})} on:click={close}>×</button></header>
 <label>{$t('ui.shell.experienceShare.profile',{default:'Shared content'})}<select aria-label={$t('ui.shell.experienceShare.profile',{default:'Shared content'})} bind:value={profile} on:change={refresh}><option value="distribution">{$t('ui.shell.experienceShare.distribution',{default:'Distribute the experience'})}</option><option value="continuation">{$t('ui.shell.experienceShare.continuation',{default:'Resume this work'})}</option></select></label>
 <p>{profile==='distribution'?$t('ui.shell.experienceShare.distributionCopy',{default:'Chosen initial state and required dependencies. Personal history and creator preferences are excluded by the provider.'}):$t('ui.shell.experienceShare.continuationCopy',{default:'Current work state, layout and included history. Review this content before distributing it.'})}</p>
 <div class="content">{#if url}<img src={url} alt={$t('ui.shell.experienceShare.preview',{default:'Portable experience card'})} draggable="true" on:dragstart={drag}/>{/if}<div class="share-information"><div class="share-description">
 {#if busy}<p role="status">{$t('ui.shell.experienceShare.preparing',{default:'Preparing the portable card…'})}</p>{/if}{#if error}<p role="alert">{error}</p>{/if}
 {#if card}<h3>{card.title}</h3><p>{$t('ui.shell.experienceShare.dropCopy',{default:'Drag this card to another compatible Workbench, or download its PNG. Import verifies the fingerprint and required capabilities before opening it. No code is installed or executed.'})}</p>
 <ul>{#each card.requirements.toolIds as id (id)}<li><code>{id}</code></li>{/each}</ul><p>{$t('ui.shell.experienceShare.qrCopy',{default:'The QR identifies the content. It does not publish or host the experience online.'})}</p>
 {/if}</div>
 {#if card} <div class="actions"><button on:click={()=>download('png')}>{$t('ui.shell.experienceShare.downloadPng',{default:'Download the PNG card'})}</button><button on:click={()=>download('json')}>{$t('ui.shell.experienceShare.downloadJson',{default:'Download the definition'})}</button></div>
 <details class="definition-inspector"><summary>{$t('ui.shell.experienceShare.definition',{default:'Exported definition'})}</summary><div class="definition-modes"><button aria-pressed={definitionMode==='tree'} on:click={()=>definitionMode='tree'}>{$t('ui.shell.experienceShare.tree',{default:'Tree'})}</button><button aria-pressed={definitionMode==='json'} on:click={()=>definitionMode='json'}>JSON</button></div><div class="definition-body">{#if definitionMode==='tree'}<StructuredValueNode name="experience" value={card} moreLabel={$t('ui.shell.experienceShare.more',{default:'Show more'})}/>{:else}<pre>{JSON.stringify(card,null,2)}</pre>{/if}</div></details>{/if}
 </div></div>
</div></div>{/if}
<style>
 .share-overlay{position:fixed;inset:0;z-index:10020;display:grid;place-items:center}.backdrop{position:absolute;inset:0;border:0;background:var(--color-background-overlay)}.share-panel{position:relative;width:min(850px,calc(100vw - 36px));max-height:calc(100vh - 44px);overflow:auto;padding:18px;box-sizing:border-box;border:1px solid var(--color-border-subtle);border-radius:8px;background:var(--color-background-surface);color:var(--color-text-primary);font-size:13px}header,.actions{display:flex;gap:10px;align-items:center}header h2{flex:1;font-size:18px;margin:0 0 12px}label{display:flex;gap:10px;align-items:center}p{line-height:1.6;color:var(--color-text-secondary)}.content{display:grid;grid-template-columns:minmax(170px,310px) minmax(0,1fr);gap:20px;margin-top:12px}.content img{width:100%;max-height:60vh;object-fit:contain;cursor:grab}button,select{font:inherit;background:var(--color-background-muted);color:inherit;border:1px solid var(--color-border-subtle);border-radius:4px;padding:7px;cursor:pointer}.actions{flex-wrap:wrap}code{overflow-wrap:anywhere}@media(max-width:600px){.content{grid-template-columns:1fr}.content img{max-height:40vh}}
.content{align-items:stretch}.share-information{display:flex;flex-direction:column;height:0;min-height:100%;max-height:100%;overflow:hidden;min-width:0;gap:12px}.share-description{flex:1;min-height:0;overflow:auto}.definition-inspector{flex:none;border-top:1px solid var(--color-border-subtle);padding-top:12px}.definition-inspector>summary{cursor:pointer;font-weight:500;padding:4px 0}.definition-modes{display:flex;gap:6px;padding:8px 0}.definition-modes button{font-size:12px;padding:4px 8px}.definition-modes button[aria-pressed=true]{border-color:var(--color-text-secondary)}.definition-body{max-height:210px;overflow:auto;scrollbar-gutter:stable;border:1px solid var(--color-border-subtle);border-radius:5px;padding:8px;background:var(--color-background-muted)}pre{font:12px/1.6 ui-monospace,monospace;margin:0;white-space:pre;tab-size:2}@media(max-width:600px){.share-information{height:400px;min-height:0;max-height:none}}
.definition-inspector[open]{background:color-mix(in srgb,var(--color-background-surface) 90%,var(--color-text-primary) 10%);border:1px solid var(--color-border-subtle);border-radius:7px;padding:10px;box-sizing:border-box}.definition-inspector[open] .definition-body{background:color-mix(in srgb,var(--color-background-surface) 95%,var(--color-text-primary) 5%)}
</style>
